// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: from address, value v, and array length n (used to build _tos)
    // We cannot fuzz raw addresses for the callee behavior, so we deploy a helper that
    // implements a function matching transferFrom(address,address,uint256) and returns (bool)
    // but we design it so the low-level call succeeds (does not revert) and returns true.
    function testFuzz_property(address from, uint256 v, uint256 n) public {
        // keep n reasonable but allow 0 to be rejected by require in C; we need non-empty
        uint256 len = bound(n, 1, 5);

        // Deploy a helper callee that has the function selector and returns true without reverting.
        HonestCallee helper = new HonestCallee();

        // Build the _tos array filled with distinct addresses (use the helper address repeatedly)
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(helper);

        // Call transfer on the reference contract c. We capture whether it returns true or false
        // using try/catch since the call could revert on wrong inputs; the reference is expected
        // not to revert for these inputs because we ensured tos.length>0 and helper does not revert.
        bool ok;
        try c.transfer(from, address(helper), tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // GENERAL RULE ASSERTION (single assertTrue): The reference contract always returns true
        // (ok == true) for any non-empty _tos when the callee's low-level call does not revert.
        // The mutant inverts the check and will return false in this scenario for some inputs.
        assertTrue(ok);
    }
}

// Adversarial/helper callee: provides a function matching selector transferFrom(address,address,uint256)
// and returns true (does not revert), so low-level call succeeds and reports success.
contract HonestCallee {
    // signature: transferFrom(address,address,uint256) -> returns (bool)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
